const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const routeKey='eliteMilesSearch', bookingKey='eliteMilesBooking', ticketsKey='eliteMilesTickets';
function getStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))||fallback}catch{return fallback}}
function saveStore(k,v){localStorage.setItem(k,JSON.stringify(v))}
function toast(msg){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.append(t)}t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function initSearch(){const form=$('#searchForm');if(!form)return;const d=$('#travelDate');if(d){const today=new Date();d.min=today.toISOString().slice(0,10);if(!d.value)d.value=d.min}$('#swapRoute')?.addEventListener('click',()=>{const a=$('#fromCity'),b=$('#toCity');[a.value,b.value]=[b.value,a.value]});form.addEventListener('submit',e=>{e.preventDefault();const data={from:$('#fromCity').value.trim(),to:$('#toCity').value.trim(),date:$('#travelDate').value,passengers:$('#passengers').value||'1'};if(!data.from||!data.to){toast('Enter both departure and destination cities.');return}if(data.from.toLowerCase()===data.to.toLowerCase()){toast('Choose two different cities.');return}saveStore(routeKey,data);location.href='../2-bus-results/index.html'})}

