{from:'Chennai',to:'Maldives',operator:'Elite Miles Air Connect',type:'Flight · Economy',departure:'06:30',arrival:'09:45',duration:'3h 15m',price:50000,rating:'4.7',amenities:'Cabin baggage · Meal · Window seat option' ,mode:'flight'}
