function cityMatch(a,b){const x=a.toLowerCase().replace(/\s+/g,' ').trim(),y=b.toLowerCase().replace(/\s+/g,' ').trim();if(x===y)return true;if(x.includes('/')||y.includes('/')){const parts=s=>s.split('/').map(v=>v.trim());return parts(x).some(p=>parts(y).some(q=>p===q||p.includes(q)||q.includes(p)))}return x===y} function routePairMatch(b,q){return (cityMatch(b.from,q.from)&&cityMatch(b.to,q.to))||(cityMatch(b.from,q.to)&&cityMatch(b.to,q.from))}
function renderBuses(){const list=$('#busList');if(!list)return;const q=getStore(routeKey,{from:'Chennai',to:'Bengaluru',date:new Date().toISOString().slice(0,10),passengers:'2'});$('#journeyRoute').textContent=`${q.from} → ${q.to}`;$('#journeyDate').textContent=`${q.date||'Select date'} · ${q.passengers} passenger(s)`;if($('#maxPrice')&&((q.to||'').toLowerCase().includes('maldives')||(q.from||'').toLowerCase().includes('maldives'))){$('#maxPrice').value='60000';$('#maxPriceLabel').textContent='₹60000';}const filters=$$('input[data-filter]');function paint(){let arr=buses.filter(b=>routePairMatch(b,q)).map((b,i)=>({...b,id:buses.indexOf(b)}));const max=Number($('#maxPrice')?.value||((q.to||'').toLowerCase().includes('maldives')|| (q.from||'').toLowerCase().includes('maldives') ? 60000 : 3500));arr=arr.filter(b=>b.price<=max);if($('#acOnly')?.checked)arr=arr.filter(b=>b.type.includes('AC'));if($('#sleeperOnly')?.checked)arr=arr.filter(b=>b.type.toLowerCase().includes('sleeper'));const sort=$('#sortBy')?.value;if(sort==='low')arr.sort((a,b)=>a.price-b.price);if(sort==='high')arr.sort((a,b)=>b.price-a.price);if(sort==='rating')arr.sort((a,b)=>Number(b.rating)-Number(a.rating));$('#resultCount').textContent=`${arr.length} buses found`;list.innerHTML=arr.map(b=>`<article class="bus-card"><div class="bus-photo has-image"><img src="${cityImage(b.to)}" alt="${b.to}"></div><div><div class="bus-name">${b.operator}</div><div class="chips"><span class="chip">${b.type}</span><span class="chip">${b.mode==='flight'?'Flight / International':'AC / Intercity'}</span><span class="chip">★ ${b.rating}</span></div><div class="bus-meta"><span>◷ ${b.departure} → ${b.arrival}</span><span>${b.duration}</span><span>${b.amenities}</span></div><p class="muted" style="margin:7px 0 0;font-size:12px">${q.from} → ${q.to}</p></div><div class="bus-side"><div class="price">₹${b.price.toLocaleString('en-IN')}</div><small>per passenger · sample fare</small><button class="btn small choose-bus" data-id="${b.id}">${b.mode==='flight'?'Choose seats →':'View seats →'}</button></div></article>`).join('')||'<div class="card empty">No Elite Miles routes match this journey. Try another route or a higher price range.</div>';$$('.choose-bus',list).forEach(btn=>btn.onclick=()=>{const b=buses[Number(btn.dataset.id)];saveStore(bookingKey,{bus:b.operator,type:b.type,departure:b.departure,arrival:b.arrival,duration:b.duration,price:b.price,seats:[],route:q});location.href='../3-booking-details/index.html'})}filters.forEach(el=>el.addEventListener('change',paint));$('#maxPrice')?.addEventListener('input',()=>{$('#maxPriceLabel').textContent='₹'+$('#maxPrice').value;paint()});$('#sortBy')?.addEventListener('change',paint);$('#changeSearch')?.addEventListener('click',()=>location.href='../1-home-search/index.html');paint()}
function initBooking(){const root=$('#bookingRoot');if(!root)return;const b=getStore(bookingKey,null),q=getStore(routeKey,{from:'Chennai',to:'Bengaluru',date:'',passengers:'1'});if(!b){root.innerHTML='<div class="card empty">Choose a bus first. <p><a class="btn" href="../2-bus-results/index.html">Browse buses</a></p></div>';return}const passengerCount=Number(q.passengers)||1;const base=Number(b.price)*passengerCount;const isFlight=b.mode==='flight';let selected=b.seats||[];const occupied=[3,7,10,14,19,23,27];root.innerHTML=`<div class="booking-grid"><section class="card"><h3>Journey summary</h3><div class="bus-photo has-image" style="height:130px;margin-bottom:14px"><img src="${cityImage(b.route?.to||q.to)}" alt="Destination"></div><strong>${b.bus}</strong><div class="chips"><span class="chip">${b.type}</span><span class="chip">${isFlight?'Flight':'Bus'}</span><span class="chip">${passengerCount} passenger(s)</span></div><div class="summary-line"><span>Route</span><strong>${q.from} → ${q.to}</strong></div><div class="summary-line"><span>Date</span><strong>${q.date||'Selected date'}</strong></div><div class="summary-line"><span>Departure</span><strong>${b.departure}</strong></div><div class="summary-line"><span>Arrival</span><strong>${b.arrival}</strong></div><div class="summary-line"><span>Selected seats</span><strong id="seatSummary">${selected.join(', ')||'None yet'}</strong></div><div class="summary-line"><span>Base fare</span><strong id="baseFare">₹${base.toLocaleString('en-IN')}</strong></div><div class="summary-line"><span>Convenience fee</span><span>₹40</span></div><div class="summary-line"><span>GST (5%)</span><span id="gst">₹${Math.round(base*.05)}</span></div><div class="summary-line total"><span>Total</span><span id="totalFare">₹${(base+40+Math.round(base*.05)).toLocaleString('en-IN')}</span></div></section><section class="card"><h3>Passenger details</h3><form id="passengerForm" class="input-stack"><div><label for="fullName">Full name</label><input id="fullName" required placeholder="Enter passenger name"></div><div><label for="phone">Mobile number</label><input id="phone" type="tel" pattern="[0-9]{10}" required placeholder="10-digit mobile number"></div><div><label for="email">Email address</label><input id="email" type="email" required placeholder="you@example.com"></div><h3 style="margin:8px 0 0">Payment method</h3><label class="payment-option"><input type="radio" name="payment" value="UPI" checked> UPI (Google Pay, PhonePe, etc.)</label><label class="payment-option"><input type="radio" name="payment" value="Card"> Credit / Debit Card</label><label class="payment-option"><input type="radio" name="payment" value="Net Banking"> Net Banking</label><label class="payment-option"><input type="radio" name="payment" value="Wallet"> Wallet</label><button class="btn" type="submit">Confirm demo booking →</button><p class="muted" style="font-size:11px;margin:0">Demo only. No real payment will be taken.</p></form></section><section class="card seat-card"><h3>${isFlight?'Choose cabin seats':'Select your seats'}</h3><div class="seat-legend"><span><i class="seat-dot" style="background:#d1fae5"></i>Available</span><span><i class="seat-dot" style="background:#d81920"></i>Selected</span><span><i class="seat-dot" style="background:#e2e8f0"></i>Occupied</span></div><div class="seat-map"><div class="driver">DRIVER / FRONT ↑</div><div id="seatGrid">${Array.from({length:8},(_,r)=>`<div class="seat-row">${[0,1,2,3].map(c=>{const n=r*4+c+1;return `<button type="button" class="seat ${occupied.includes(n)?'occupied':''} ${selected.includes('A'+n)?'selected':''}" data-seat="A${n}" aria-label="Seat A${n}" ${occupied.includes(n)?'disabled':''}><img src="../assets/icons/armchair.svg" alt=""><span>A${n}</span></button>`}).join('')}</div>`).join('')}</div><div class="driver" style="border:0;border-top:1px dashed #cbd5e1;padding:10px 0 0;margin:12px 0 0;text-align:center">REAR</div></div><p class="muted" style="font-size:11px">Select up to ${passengerCount} ${isFlight?'cabin seat(s)':'seat(s)'}. Demo ${isFlight?'flight':'bus'} layout.</p></section></div>`;
function update(){const sum=selected.join(', ')||'None yet';$('#seatSummary').textContent=sum;const total=base+40+Math.round(base*.05);$('#totalFare').textContent='₹'+total.toLocaleString('en-IN');$('#seatGrid').querySelectorAll('.seat:not(.occupied)').forEach(el=>el.classList.toggle('selected',selected.includes(el.dataset.seat)));saveStore(bookingKey,{...b,seats:selected,route:q,total})}$('#seatGrid').addEventListener('click',e=>{const el=e.target.closest('[data-seat]');if(!el||el.disabled)return;const s=el.dataset.seat;if(selected.includes(s))selected=selected.filter(x=>x!==s);else if(selected.length<passengerCount)selected.push(s);else toast(`Select up to ${passengerCount} seat(s).`);update()});$('#passengerForm').addEventListener('submit',e=>{e.preventDefault();if(selected.length!==passengerCount){toast(`Please select ${passengerCount} seat(s).`);return}const form={name:$('#fullName').value,phone:$('#phone').value,email:$('#email').value,payment:$('input[name="payment"]:checked').value};const ticket={...getStore(bookingKey,{}),...form,bookingId:'EM'+Date.now().toString().slice(-7),status:'Confirmed',date:q.date||new Date().toISOString().slice(0,10),createdAt:new Date().toISOString()};const tickets=getStore(ticketsKey,[]);tickets.unshift(ticket);saveStore(ticketsKey,tickets);saveStore(bookingKey,ticket);toast('Demo ticket confirmed!');setTimeout(()=>location.href='../4-profile-tickets/index.html',700)});update()}
function initProfile(){const upcoming=$('#upcomingTickets'),past=$('#pastTickets');if(!upcoming)return;const tickets=getStore(ticketsKey,[]);if(!tickets.length){upcoming.innerHTML='<div class="empty">No bookings yet. Your confirmed demo tickets will appear here.</div>';$('#bookingCount').textContent='0';$('#upcomingCount').textContent='0';}else{const markup=t=>`<article class="ticket-card"><div class="ticket-thumb"><img src="${cityImage(t.route?.to||t.route?.from)}" alt="Destination" style="width:100%;height:100%;object-fit:cover;border-radius:10px"></div><div class="ticket-info"><strong>${t.route?.from||'City'} → ${t.route?.to||'Destination'}</strong><span class="muted">${t.date||'Date not set'} · ${t.departure||''}</span><div class="muted" style="font-size:12px">${t.bus||'Bus operator'} · Seat(s): ${(t.seats||[]).join(', ')}</div><span class="status">${t.status||'Confirmed'}</span></div><div style="text-align:right"><strong>₹${Number(t.total||t.price||0).toLocaleString('en-IN')}</strong><br><button class="btn small outline ticket-view" data-id="${t.bookingId}">View ticket</button></div></article>`;upcoming.innerHTML=tickets.map(markup).join('');past.innerHTML=tickets.slice(1).map(markup).join('')||'<div class="empty">Your past trips will appear here.</div>';$('#bookingCount').textContent=String(tickets.length);$('#upcomingCount').textContent=String(tickets.length);$$('.ticket-view').forEach(btn=>btn.addEventListener('click',()=>{const t=tickets.find(x=>x.bookingId===btn.dataset.id);alert(`Elite Miles e-ticket\nBooking ID: ${t.bookingId}\nRoute: ${t.route?.from} → ${t.route?.to}\nDate: ${t.date}\nPassenger: ${t.name}\nSeats: ${t.seats.join(', ')}\nStatus: ${t.status}`)}))}$('#editProfile')?.addEventListener('click',()=>toast('Profile editing is a demo feature.'));$('#clearDemo')?.addEventListener('click',()=>{if(confirm('Clear all demo bookings from this browser?')){localStorage.removeItem(ticketsKey);localStorage.removeItem(bookingKey);location.reload()}})}
document.addEventListener('DOMContentLoaded',()=>{initSearch();renderBuses();initBooking();initProfile()});
